<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class UpbringingRiskSignals extends Page{protected static ?string $navigationIcon='heroicon-o-exclamation';protected static ?string $navigationLabel='Сигналы риска';protected static ?string $navigationGroup='Воспитательная работа';protected static string $view='filament.pages.upbringing-risk-signals';public array $rows=[];
public function mount():void{$p=request()->attributes->get('academic_period');if(!$p)return;$att=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where('l.academic_period_id',$p->id)->groupBy('a.student_id')->select('a.student_id',DB::raw('COUNT(*) total'),DB::raw("SUM(CASE WHEN a.status IN ('absent','late') THEN 1 ELSE 0 END) concerns"))->get()->keyBy('student_id');$gr=DB::table('grade_records as g')->join('lesson_occurrences as l','l.id','=','g.lesson_occurrence_id')->where('l.academic_period_id',$p->id)->whereRaw("g.value REGEXP '^[0-9]+([.][0-9]+)?$'")->groupBy('g.student_id')->select('g.student_id',DB::raw('AVG(CAST(g.value AS DECIMAL(5,2))) avg_grade'),DB::raw("SUM(CASE WHEN CAST(g.value AS DECIMAL(5,2))<=2 THEN 1 ELSE 0 END) low_count"))->get()->keyBy('student_id');$this->rows=DB::table('student_group_memberships as m')->join('students as s','s.id','=','m.student_id')->join('study_groups as sg','sg.id','=','m.study_group_id')->where('m.academic_period_id',$p->id)->where('m.status','active')->select('s.id','s.last_name','s.first_name','sg.name as group_name')->get()->map(function($s)use($att,$gr){$a=$att->get($s->id);$g=$gr->get($s->id);$s->concerns=$a?(int)$a->concerns:0;$s->total=$a?(int)$a->total:0;$s->absence_rate=$s->total?round($s->concerns*100/$s->total,1):0;$s->avg_grade=$g?round($g->avg_grade,2):null;$s->low_count=$g?(int)$g->low_count:0;return (array)$s;})->filter(fn($x)=>$x['absence_rate']>=20||$x['low_count']>=3)->values()->all();}public static function canAccess():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->canDo('upbringing.view'));}}